class Solution {
public:
    vector<int> distanceToCycle(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        vector<int> deg(n, 0);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
            deg[e[0]]++;
            deg[e[1]]++;
        }

        queue<int> q;
        for (int i = 0; i < n; i++) {
            if (deg[i] == 1) q.push(i);
        }

        vector<bool> inCycle(n, true);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            inCycle[u] = false;
            for (int v : adj[u]) {
                deg[v]--;
                if (deg[v] == 1) q.push(v);
            }
        }

        vector<int> dist(n, -1);
        queue<int> bq;
        for (int i = 0; i < n; i++) {
            if (inCycle[i]) {
                dist[i] = 0;
                bq.push(i);
            }
        }

        while (!bq.empty()) {
            int u = bq.front();
            bq.pop();
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    bq.push(v);
                }
            }
        }
        return dist;
    }
};

class Solution {
    public int[] distanceToCycle(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        int[] deg = new int[n];
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
            deg[e[0]]++;
            deg[e[1]]++;
        }

        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (deg[i] == 1) q.add(i);
        }

        boolean[] inCycle = new boolean[n];
        Arrays.fill(inCycle, true);
        while (!q.isEmpty()) {
            int u = q.poll();
            inCycle[u] = false;
            for (int v : adj.get(u)) {
                deg[v]--;
                if (deg[v] == 1) q.add(v);
            }
        }

        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Queue<Integer> bq = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (inCycle[i]) {
                dist[i] = 0;
                bq.add(i);
            }
        }

        while (!bq.isEmpty()) {
            int u = bq.poll();
            for (int v : adj.get(u)) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    bq.add(v);
                }
            }
        }
        return dist;
    }
}

