var distanceToCycle = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    const deg = new Array(n).fill(0);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
        deg[u]++;
        deg[v]++;
    }

    const q = [];
    for (let i = 0; i < n; i++) {
        if (deg[i] === 1) q.push(i);
    }

    const inCycle = new Array(n).fill(true);
    let head = 0;
    while (head < q.length) {
        const u = q[head++];
        inCycle[u] = false;
        for (const v of adj[u]) {
            deg[v]--;
            if (deg[v] === 1) q.push(v);
        }
    }

    const dist = new Array(n).fill(-1);
    const bq = [];
    for (let i = 0; i < n; i++) {
        if (inCycle[i]) {
            dist[i] = 0;
            bq.push(i);
        }
    }

    let bhead = 0;
    while (bhead < bq.length) {
        const u = bq[bhead++];
        for (const v of adj[u]) {
            if (dist[v] === -1) {
                dist[v] = dist[u] + 1;
                bq.push(v);
            }
        }
    }
    return dist;
};
